use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        match &self.root_node {
            Some(root) => root.borrow().left_child_count + root.borrow().right_child_count + 1,
            None => 0,
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: None,
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        let mut current = self.root_node.clone();
        let mut parent: Option<Rc<RefCell<BOSNode>>> = None;
        let mut is_left_child = true;

        while let Some(ref node) = current {
            parent = current.clone();
            let cmp = (self.cmp_function)(&new_node.borrow().key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                current = node.borrow().left_child_node.clone();
                is_left_child = true;
            } else {
                node.borrow_mut().right_child_count += 1;
                current = node.borrow().right_child_node.clone();
                is_left_child = false;
            }
        }

        new_node.borrow_mut().parent_node = parent.as_ref().map(|p| Rc::downgrade(p));

        if let Some(ref parent_node) = parent {
            if is_left_child {
                parent_node.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent_node.borrow_mut().right_child_node = Some(new_node.clone());
            }
            Self::update_depths_and_rebalance(self, &parent_node);
        } else {
            self.root_node = Some(new_node.clone());
        }

        new_node
    }

    fn update_depths_and_rebalance(tree: &mut BOSTree, node: &Rc<RefCell<BOSNode>>) {
        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();

        if has_left ^ has_right {
            node.borrow_mut().depth += 1;

            let mut current = Some(node.clone());
            while let Some(ref node_ref) = current {
                if let Some(parent_weak) = node_ref.borrow().parent_node.clone() {
                    if let Some(parent) = parent_weak.upgrade() {
                        let new_left_depth = parent.borrow().left_child_node.as_ref()
                            .map_or(0, |n| n.borrow().depth + 1);
                        let new_right_depth = parent.borrow().right_child_node.as_ref()
                            .map_or(0, |n| n.borrow().depth + 1);
                        let max_depth = std::cmp::max(new_left_depth, new_right_depth);

                        if parent.borrow().depth != max_depth {
                            parent.borrow_mut().depth = max_depth;
                        } else {
                            break;
                        }

                        let balance = Self::get_balance(&parent);
                        if new_left_depth as i32 - 2 == new_right_depth as i32 {
                            if Self::get_balance(&parent.borrow().left_child_node.as_ref().unwrap()) > 0 {
                                Self::rotate_left(tree, &parent.borrow().left_child_node.as_ref().unwrap());
                            }
                            Self::rotate_right(tree, &parent);
                        } else if new_left_depth + 2 == new_right_depth {
                            if Self::get_balance(&parent.borrow().right_child_node.as_ref().unwrap()) < 0 {
                                Self::rotate_right(tree, &parent.borrow().right_child_node.as_ref().unwrap());
                            }
                            Self::rotate_left(tree, &parent);
                        }

                        current = Some(parent);
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
    }

    fn get_balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
        let left_depth = node.borrow().left_child_node.as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        let right_depth = node.borrow().right_child_node.as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        right_depth as i32 - left_depth as i32
    }

    fn rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) {
        let l = p.borrow().left_child_node.clone();
        if l.is_none() {
            return;
        }
        let l = l.unwrap();

        let p_parent = p.borrow().parent_node.clone();
        if let Some(ref parent_weak) = p_parent {
            if let Some(parent) = parent_weak.upgrade() {
                if parent.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, p)) {
                    parent.borrow_mut().left_child_node = Some(l.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(l.clone());
                }
            }
        } else {
            tree.root_node = Some(l.clone());
        }
        l.borrow_mut().parent_node = p_parent;

        let l_right = l.borrow().right_child_node.clone();
        p.borrow_mut().left_child_node = l_right.clone();
        if let Some(ref lr) = l_right {
            lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }
        p.borrow_mut().left_child_count = l.borrow().right_child_count;

        let p_left_depth = p.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let p_right_depth = p.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        p.borrow_mut().depth = std::cmp::max(p_left_depth, p_right_depth);

        l.borrow_mut().right_child_node = Some(p.clone());
        p.borrow_mut().parent_node = Some(Rc::downgrade(&l));
        l.borrow_mut().right_child_count = p.borrow().left_child_count + p.borrow().right_child_count + 1;

        let l_left_depth = l.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let l_right_depth = l.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        l.borrow_mut().depth = std::cmp::max(l_left_depth, l_right_depth);
    }

    fn rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) {
        let r = p.borrow().right_child_node.clone();
        if r.is_none() {
            return;
        }
        let r = r.unwrap();

        let p_parent = p.borrow().parent_node.clone();
        if let Some(ref parent_weak) = p_parent {
            if let Some(parent) = parent_weak.upgrade() {
                if parent.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, p)) {
                    parent.borrow_mut().left_child_node = Some(r.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(r.clone());
                }
            }
        } else {
            tree.root_node = Some(r.clone());
        }
        r.borrow_mut().parent_node = p_parent;

        let r_left = r.borrow().left_child_node.clone();
        p.borrow_mut().right_child_node = r_left.clone();
        if let Some(ref rl) = r_left {
            rl.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }
        p.borrow_mut().right_child_count = r.borrow().left_child_count;

        let p_left_depth = p.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let p_right_depth = p.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        p.borrow_mut().depth = std::cmp::max(p_left_depth, p_right_depth);

        r.borrow_mut().left_child_node = Some(p.clone());
        p.borrow_mut().parent_node = Some(Rc::downgrade(&r));
        r.borrow_mut().left_child_count = p.borrow().left_child_count + p.borrow().right_child_count + 1;

        let r_left_depth = r.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let r_right_depth = r.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        r.borrow_mut().depth = std::cmp::max(r_left_depth, r_right_depth);
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let node_has_two_children = node.borrow().left_child_node.is_some() && node.borrow().right_child_node.is_some();

        if node_has_two_children {
            self.remove_two_children(node);
        } else {
            self.remove_one_or_zero_children(node);
        }

        self.bostree_node_weak_unref(node);
    }

    fn remove_two_children(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let left_depth = node.borrow().left_child_node.as_ref().unwrap().borrow().depth;
        let right_depth = node.borrow().right_child_node.as_ref().unwrap().borrow().depth;

        let (candidate, lost_child, bubble_start_weak) = if left_depth >= right_depth {
            node.borrow_mut().left_child_count -= 1;
            let candidate = Self::find_rightmost(&node.borrow().left_child_node.as_ref().unwrap());
            let lost_child = candidate.borrow().left_child_node.clone();
            let bubble_start = candidate.borrow().parent_node.clone();
            (candidate, lost_child, bubble_start)
        } else {
            node.borrow_mut().right_child_count -= 1;
            let candidate = Self::find_leftmost(&node.borrow().right_child_node.as_ref().unwrap());
            let lost_child = candidate.borrow().right_child_node.clone();
            let bubble_start = candidate.borrow().parent_node.clone();
            (candidate, lost_child, bubble_start)
        };

        if let Some(ref bubble_start_w) = bubble_start_weak {
            if let Some(bubble_start) = bubble_start_w.upgrade() {
                if bubble_start.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, &candidate)) {
                    bubble_start.borrow_mut().left_child_node = lost_child.clone();
                } else {
                    bubble_start.borrow_mut().right_child_node = lost_child.clone();
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(bubble_start_w.clone());
                }
            }
        }

        let node_parent_weak = node.borrow().parent_node.clone();
        if let Some(ref parent_weak) = node_parent_weak {
            if let Some(parent) = parent_weak.upgrade() {
                if parent.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, node)) {
                    parent.borrow_mut().left_child_node = Some(candidate.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(candidate.clone());
                }
            }
        } else {
            self.root_node = Some(candidate.clone());
        }
        candidate.borrow_mut().parent_node = node_parent_weak;

        candidate.borrow_mut().left_child_node = node.borrow().left_child_node.clone();
        candidate.borrow_mut().left_child_count = node.borrow().left_child_count;
        candidate.borrow_mut().right_child_node = node.borrow().right_child_node.clone();
        candidate.borrow_mut().right_child_count = node.borrow().right_child_count;

        if let Some(ref left) = candidate.borrow().left_child_node {
            left.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
        }
        if let Some(ref right) = candidate.borrow().right_child_node {
            right.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
        }

        let left_depth = candidate.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let right_depth = candidate.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        candidate.borrow_mut().depth = std::cmp::max(left_depth, right_depth);

        let mut bubble_up = candidate.borrow().parent_node.clone().and_then(|w| w.upgrade());

        if let Some(ref bu) = bubble_up {
            if bu.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, &candidate)) {
                bu.borrow_mut().left_child_count -= 1;
            } else {
                bu.borrow_mut().right_child_count -= 1;
            }
        }

        node.borrow_mut().weak_ref_node_valid = 0;

        self.rebalance_up(bubble_up);
    }

    fn remove_one_or_zero_children(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let candidate = if node.borrow().left_child_node.is_some() {
            node.borrow().left_child_node.clone()
        } else {
            node.borrow().right_child_node.clone()
        };

        if node.borrow().parent_node.is_none() {
            self.root_node = candidate.clone();
            if let Some(ref c) = candidate {
                c.borrow_mut().parent_node = None;
            }
            node.borrow_mut().weak_ref_node_valid = 0;
            return;
        }

        let node_parent_weak = node.borrow().parent_node.clone();
        if let Some(ref parent_weak) = node_parent_weak {
            if let Some(parent) = parent_weak.upgrade() {
                let candidate_count = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_count
                } else {
                    node.borrow().right_child_count
                };

                if parent.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, node)) {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = candidate_count;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = candidate_count;
                }

                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Some(parent_weak.clone());
                }

                node.borrow_mut().weak_ref_node_valid = 0;

                self.rebalance_up(Some(parent));
            }
        }
    }

    fn rebalance_up(&mut self, mut bubble_up: Option<Rc<RefCell<BOSNode>>>) {
        while let Some(ref bu) = bubble_up {
            let new_depth = {
                let left_depth = bu.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let right_depth = bu.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                std::cmp::max(left_depth, right_depth)
            };
            let depth_changed = new_depth != bu.borrow().depth;
            bu.borrow_mut().depth = new_depth;

            let balance = Self::get_balance(bu);
            if balance < -1 {
                if Self::get_balance(&bu.borrow().left_child_node.as_ref().unwrap()) > 0 {
                    Self::rotate_left(self, &bu.borrow().left_child_node.as_ref().unwrap());
                }
                let new_bu = bu.borrow().parent_node.clone().and_then(|w| w.upgrade());
                Self::rotate_right(self, bu);
                bubble_up = new_bu;
            } else if balance > 1 {
                if Self::get_balance(&bu.borrow().right_child_node.as_ref().unwrap()) < 0 {
                    Self::rotate_right(self, &bu.borrow().right_child_node.as_ref().unwrap());
                }
                let new_bu = bu.borrow().parent_node.clone().and_then(|w| w.upgrade());
                Self::rotate_left(self, bu);
                bubble_up = new_bu;
            } else {
                if !depth_changed {
                    break;
                }
                bubble_up = bu.borrow().parent_node.clone().and_then(|w| w.upgrade());
            }
        }
    }

    fn find_rightmost(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let mut current = node.clone();
        while current.borrow().right_child_node.is_some() {
            let next = current.borrow().right_child_node.clone().unwrap();
            current = next;
        }
        current
    }

    fn find_leftmost(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let mut current = node.clone();
        while current.borrow().left_child_node.is_some() {
            let next = current.borrow().left_child_node.clone().unwrap();
            current = next;
        }
        current
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        {
            let mut node_ref = node.borrow_mut();
            if node_ref.weak_ref_count > 0 {
                node_ref.weak_ref_count -= 1;
            }
        }
        if node.borrow().weak_ref_count == 0 {
            if let Some(ref free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else if node.borrow().weak_ref_node_valid != 0 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(ref node) = current {
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(node.clone());
            } else if cmp < 0 {
                current = node.borrow().left_child_node.clone();
            } else {
                current = node.borrow().right_child_node.clone();
            }
        }
        None
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        while let Some(ref node) = current {
            if node.borrow().left_child_count as u32 <= idx {
                idx -= node.borrow().left_child_count as u32;
                if idx == 0 {
                    return Some(node.clone());
                }
                idx -= 1;
                current = node.borrow().right_child_node.clone();
            } else {
                current = node.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        println!("BOSTree debug print");
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    {
        let mut node_ref = node.borrow_mut();
        if node_ref.weak_ref_count < 127 {
            node_ref.weak_ref_count += 1;
        }
    }
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref right) = node.borrow().right_child_node {
        let mut current = right.clone();
        while let Some(ref left) = current.borrow().left_child_node {
            current = left.clone();
        }
        return Some(current);
    }
    let mut current = node.clone();
    loop {
        if let Some(ref parent_weak) = current.borrow().parent_node {
            if let Some(parent) = parent_weak.upgrade() {
                if parent.borrow().right_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, &current)) {
                    current = parent.clone();
                    continue;
                }
                return Some(parent.clone());
            }
        }
        return None;
    }
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(ref left) = node.borrow().left_child_node {
        let mut current = left.clone();
        while let Some(ref right) = current.borrow().right_child_node {
            current = right.clone();
        }
        return Some(current);
    }
    let mut current = node.clone();
    loop {
        if let Some(ref parent_weak) = current.borrow().parent_node {
            if let Some(parent) = parent_weak.upgrade() {
                if parent.borrow().left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, &current)) {
                    current = parent.clone();
                    continue;
                }
                return Some(parent.clone());
            }
        }
        return None;
    }
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = node.clone();
    loop {
        if let Some(ref parent_weak) = current.borrow().parent_node {
            if let Some(parent) = parent_weak.upgrade() {
                if parent.borrow().right_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, &current)) {
                    counter += 1 + parent.borrow().left_child_count;
                }
                current = parent;
            } else {
                break;
            }
        } else {
            break;
        }
    }
    counter
}
